'''# locate boundary rows 8192 / 8193: binary search on family size, then filler words
cache = {}
lo, hi = 1024, 4096
while lo < hi:
    mid = (lo + hi) // 2
    cache[mid] = count_rows(family(mid))
    if cache[mid] < 8192:
        lo = mid + 1
    else:
        hi = mid
for n in range(max(1024, lo - 3), min(4096, lo + 4)):
    cache[n] = count_rows(family(n))
print("   rows near boundary:", {n: cache[n] for n in sorted(cache) if 8185 <= cache[n] <= 8200})

# find base n just under 8192 and fill with single words adding 1..3 rows each
base_n = max(n for n in cache if cache[n] <= 8192)
base = family(base_n)
fillers = []
for k in (0, 1, 2, 3, 4, 5, 6, 7):
    fillers.append(("A",)*15 + (chr(ord("A") + k),))
    fillers.append(("B",)*15 + (chr(ord("A") + k),))
    fillers.append(("A", "B")*8)
    fillers.append(("C",)*k + ("D",)*(16-k))

def reach(target):
    words = list(base)
    for w in fillers:
        if count_rows(words) >= target:
            break
        add = [w]
        if count_rows(words + add) <= target:
            words += add
    return words if count_rows(words) == target else None

for target in (8192, 8193):
    ws = reach(target)
    if ws is not None:
        expect_rows(f"boundary rows={target}", ws)
    else:
        print(f"[WARN] could not build exactly {target} rows")

summary()''')
